-- Additive, validated migration: no reassignment or deletion on invalid legacy links.
-- A cross-company link causes transaction rollback and requires explicit reconciliation.
ALTER TABLE preparation_orders ADD COLUMN org_id text;
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM preparation_orders po JOIN preparations p ON p.id=po.preparation_id JOIN orders o ON o.id=po.order_id WHERE p.org_id<>o.org_id) THEN
  RAISE EXCEPTION 'Cross-company preparation membership: reconcile source data before migration';
 END IF;
END; $$;
UPDATE preparation_orders po SET org_id=p.org_id FROM preparations p WHERE p.id=po.preparation_id;
ALTER TABLE preparation_orders ALTER COLUMN org_id SET NOT NULL;
CREATE OR REPLACE FUNCTION inherit_preparation_company() RETURNS trigger AS $$ BEGIN
 IF NEW.org_id IS NULL THEN SELECT org_id INTO NEW.org_id FROM preparations WHERE id=NEW.preparation_id; END IF;
 RETURN NEW;
END; $$ LANGUAGE plpgsql;
CREATE TRIGGER preparation_company BEFORE INSERT ON preparation_orders FOR EACH ROW EXECUTE FUNCTION inherit_preparation_company();
